<script setup>
import { onMounted, reactive, ref } from 'vue'
import { collectionApi } from '@/services/collection.service'
import { sheetApi } from '@/services/sheet.service'

const collections=ref([]),metadata=ref({courses:[]}),loading=ref(true),error=ref('')
const form=reactive({name:'',description:'',collectionType:'MIXED',courseId:'',visibility:'AUTHENTICATED'})
async function load(){loading.value=true;error.value='';try{[collections.value,metadata.value]=await Promise.all([collectionApi.mine(),sheetApi.metadata()])}catch(cause){error.value=cause.message}finally{loading.value=false}}
async function create(){try{const created=await collectionApi.create({...form,courseId:form.collectionType==='COURSE'?form.courseId:null});collections.value.unshift(created);Object.assign(form,{name:'',description:'',collectionType:'MIXED',courseId:'',visibility:'AUTHENTICATED'})}catch(cause){error.value=cause.message}}
async function act(item,action){try{Object.assign(item,await collectionApi.lifecycle(item.id,action))}catch(cause){error.value=cause.message}}
onMounted(load)
</script>
<template><section class="page-panel"><div class="panel__header"><div><p class="eyebrow">My library</p><h1>Collections ของฉัน</h1><p>จัดเอกสารเป็นลำดับและเผยแพร่ให้ผู้ใช้ที่เข้าสู่ระบบเข้าถึงได้</p></div></div>
<p v-if="error" class="form-error" role="alert">{{ error }}</p>
<form class="form collection-create" @submit.prevent="create"><label>ชื่อ Collection<input v-model.trim="form.name" maxlength="120" required></label><label>คำอธิบาย<textarea v-model.trim="form.description" maxlength="2000" rows="3" /></label><div class="form-grid"><label>ประเภท<select v-model="form.collectionType"><option value="MIXED">Mixed</option><option value="COURSE">Course</option></select></label><label v-if="form.collectionType==='COURSE'">รายวิชา<select v-model="form.courseId" required><option value="" disabled>เลือกรายวิชา</option><option v-for="course in metadata.courses" :key="course.id" :value="course.id">{{ course.code }} — {{ course.nameEn||course.name }}</option></select></label><label>การมองเห็น<select v-model="form.visibility"><option value="AUTHENTICATED">ผู้ใช้ที่เข้าสู่ระบบ</option><option value="PRIVATE">ส่วนตัว</option></select></label></div><button class="button button--primary">สร้าง Collection</button></form>
<div v-if="loading" class="empty-state">กำลังโหลด…</div><div v-else class="collection-grid"><article v-for="item in collections" :key="item.id" class="collection-card"><div><span class="type-chip">{{ item.collectionType }}</span><h2>{{ item.name }}</h2><p>{{ item.description||'ยังไม่มีคำอธิบาย' }}</p><p class="material-meta">{{ item.documentCount }} เอกสาร · {{ item.publicationStatus }}</p></div><div class="button-row"><RouterLink class="button button--primary button--small" :to="`/dashboard/collections/${item.id}/edit`">จัดการ</RouterLink><RouterLink v-if="item.publicationStatus==='PUBLISHED'" class="button button--ghost button--small" :to="`/dashboard/c/${item.slug}`">เปิดหน้าที่แชร์</RouterLink><button v-if="item.publicationStatus==='DRAFT'" class="button button--ghost button--small" @click="act(item,'publish')">เผยแพร่</button><button v-if="item.publicationStatus==='PUBLISHED'" class="button button--ghost button--small" @click="act(item,'unpublish')">ยกเลิกเผยแพร่</button><button v-if="item.publicationStatus!=='ARCHIVED'" class="button button--ghost button--small" @click="act(item,'archive')">เก็บถาวร</button></div></article></div></section></template>
